let matchTimer=null,matchFilter='highlights',matchReport=null;
function stopMatchClock(){if(matchTimer!==null)clearInterval(matchTimer);matchTimer=null;}
function pauseMatch(){stopMatchClock();if(s.liveMatch)s.liveMatch.paused=true;AutoSave.changed();const b=$('matchPlay');if(b)b.textContent='Continuar';}
function showMatch(){pauseMatch();matchReport=null;renderMatch();$('matchDialog').showModal();}
function viewMatchReport(report){pauseMatch();matchReport=report;renderMatch();$('matchDialog').showModal();}
function eventText(e){const name=id=>s.players.find(p=>p.id===id)?.name||'Jogador';const who=e.player===null?'':name(e.player);return ({kickoff:'Início do jogo',halftime:'Intervalo',fulltime:'Fim do jogo',pass:`${who}: passe ${e.complete?'completo':'interceptado'}`,recovery:`${who} recupera a bola`,attack:`${who} constrói um ataque`,shot:`${who}: remate ${e.onTarget?'à baliza':'para fora'}`,goal:`GOLO · ${who}${e.assist!==null&&e.assist!==undefined?' · Assistência: '+name(e.assist):''}`,foul:`Falta de ${who}`,yellow:`Amarelo · ${who}`,red:`Expulsão · ${who}${e.secondYellow?' (segundo amarelo)':''}`,injury:`Lesão · ${who} · ${e.matches} jornada(s) de recuperação`,save:`Defesa de ${who}`,blocked:'Remate bloqueado',substitution:`Sai ${who} · Entra ${name(e.incoming)}`,tactics:`${club(e.team)?.name||''} · ${e.formation} · ${e.tactic}`})[e.type]||e.type;}
function renderMatch(){
 AutoSave.changed();
 const m=matchReport||s.liveMatch;if(!m)return;const live=!matchReport,t=m.teams.find(t=>t.id===s.managed)||m.teams[0],canManage=live&&!m.finished,profiles=m.finalProfiles||m.teams.map(t=>Engine.profile(s,m,t));
 const aggregateLabels={shots:'Remates',shotsOnTarget:'À baliza',passes:'Passes tentados',passesCompleted:'Passes completos',recoveries:'Recuperações',fouls:'Faltas',yellow:'Amarelos',red:'Expulsões',saves:'Defesas',injuries:'Lesões'};
 const totalPoss=m.teams.reduce((n,t)=>n+t.stats.possession,0)||1;
 const playerRows=side=>side.used.map(id=>{const u=side.units[id],p=s.players.find(p=>p.id===id);return `<tr><td>${esc(p?.name||'Jogador')} ${u.red?'🟥':u.yellow?'🟨':''}${u.injuryMatches?' · Lesionado':''}</td><td>${side.roles[id]||'—'}</td><td>${u.minutes}</td><td>${u.goals}</td><td>${u.assists}</td><td>${u.passesCompleted}/${u.passes}</td><td>${u.saves}</td><td>${Math.round(u.fatigue)}%</td></tr>`;}).join('');
 const events=m.events.filter(e=>matchFilter==='all'||!['pass','recovery','attack'].includes(e.type)).slice(-60).reverse();
 $('matchDialog').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">MATCH ENGINE V1 · JORNADA ${m.round+1}</span><h2>${matchReport?'Relatório do jogo':m.finished?'Jogo concluído':m.minute===45&&m.paused?'Intervalo':m.paused?'Jogo em pausa':'Jogo em directo'}</h2></div><button id="matchClose" aria-label="Fechar jogo">×</button></div><div class="match-scoreboard"><span>${badge(club(m.home))}${esc(club(m.home).name)}</span><strong>${m.score[0]} : ${m.score[1]}<small>${m.minute}′ / 90′</small></strong><span>${badge(club(m.away))}${esc(club(m.away).name)}</span></div>
 <div class="toolbar match-controls">${canManage?`<button id="matchPlay" class="primary">${m.paused?'Continuar':'Pausar'}</button><button id="matchStep">+1 minuto</button><button id="matchFinish">Simular até ao fim</button><button id="matchSave">Guardar carreira com este jogo</button>`:''}${live&&m.finished?'<button id="matchCommit" class="primary">Concluir jornada e actualizar carreira</button>':''}<span class="muted">${live?'90 minutos · 5 substituições · pausa automática ao intervalo':'Eventos e estatísticas registados pelo motor'}</span></div>
 ${canManage?`<section class="match-tactics"><label>Formação<select id="liveFormation">${options(Engine.formations,t.formation)}</select></label><label>Mentalidade<select id="liveMentality">${options(Engine.mentalities,t.tactic)}</select></label><label>Sai<select id="subOut">${t.active.map(id=>`<option value="${id}">${esc(s.players.find(p=>p.id===id).name)} · ${t.roles[id]} · fadiga ${Math.round(t.units[id].fatigue)}%${t.units[id].injuryMatches?' · LESIONADO':''}</option>`).join('')}</select></label><label>Entra<select id="subIn">${t.bench.map(id=>`<option value="${id}">${esc(s.players.find(p=>p.id===id).name)} · ${s.players.find(p=>p.id===id).position}</option>`).join('')}</select></label><button id="makeSub" ${t.subs>=5||!t.bench.length||!t.active.length?'disabled':''}>Substituir (${t.subs}/5)</button></section>`:''}
 <p id="matchError" role="alert"></p><div class="match-columns"><section class="panel"><h3>Força actual</h3><div class="table-wrap"><table><thead><tr><th>Equipa</th><th>Ataque</th><th>Defesa</th><th>Controlo</th><th>GR</th></tr></thead><tbody>${m.teams.map((side,i)=>`<tr><td>${esc(club(side.id).name)} · ${side.active.filter(id=>!side.units[id].injuryMatches).length} em campo</td>${['attack','defence','control','keeper'].map(k=>`<td>${profiles[i][k].toFixed(1)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">${m.teams.map(side=>`${esc(club(side.id).name)}: ${side.formation} · ${side.tactic}`).join(' / ')}</p><h3>Estatísticas colectivas</h3><table><tbody><tr><td>Posse</td>${m.teams.map(side=>`<td>${Math.round(side.stats.possession/totalPoss*100)}%</td>`).join('')}</tr>${Object.entries(aggregateLabels).map(([k,label])=>`<tr><td>${label}</td><td>${m.teams[0].stats[k]}</td><td>${m.teams[1].stats[k]}</td></tr>`).join('')}</tbody></table></section><section class="panel"><div class="panel-head"><h3>Eventos</h3><select id="matchFilter" aria-label="Filtrar eventos">${options(['highlights','all'],matchFilter).replace('>highlights<','>Destaques<').replace('>all<','>Todos<')}</select></div><div class="match-events" role="log" aria-live="off">${events.map(e=>`<div class="match-event event-${e.type}"><b>${e.minute}′</b><span>${esc(eventText(e))}</span></div>`).join('')}</div><p class="muted">Últimos 60 eventos do filtro. O relatório guarda a sequência completa.</p></section></div>
 ${m.teams.map(side=>`<section class="panel match-player-stats"><h3>${esc(club(side.id).name)} · Jogadores</h3><div class="table-wrap"><table><thead><tr><th>Jogador</th><th>Pos.</th><th>Min.</th><th>G</th><th>A</th><th>Passes</th><th>Defesas</th><th>Fadiga</th></tr></thead><tbody>${playerRows(side)}</tbody></table></div></section>`).join('')}`;
 $('matchClose').onclick=()=>{pauseMatch();$('matchDialog').close();render();};$('matchDialog').oncancel=e=>{e.preventDefault();$('matchClose').click();};
 $('matchFilter').onchange=e=>{matchFilter=e.target.value;renderMatch();};
 if(canManage){const handle=fn=>{pauseMatch();try{fn();renderMatch();}catch(err){$('matchError').textContent=err.message;}};
 $('matchPlay').onclick=()=>{if(!m.paused){pauseMatch();renderMatch();return;}m.paused=false;renderMatch();stopMatchClock();matchTimer=setInterval(()=>{try{Engine.stepMatch(s,m);if(m.paused||m.finished)stopMatchClock();renderMatch();}catch(err){pauseMatch();$('matchError').textContent=err.message;}},650);};
 $('matchStep').onclick=()=>handle(()=>{m.paused=false;Engine.stepMatch(s,m);m.paused=true;});
 $('matchFinish').onclick=()=>handle(()=>Engine.playToEnd(s,m));
 $('matchSave').onclick=()=>{pauseMatch();const url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`helvetia-${s.year}-j${s.round}-min${m.minute}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);renderMatch();};
 for(const id of ['liveFormation','liveMentality','subOut','subIn'])$(id).onfocus=()=>pauseMatch();
 const tactical=()=>handle(()=>{Engine.changeTactics(s,m,t.id,$('liveFormation').value,$('liveMentality').value);s.formation=t.formation;s.tactic=t.tactic;});$('liveFormation').onchange=tactical;$('liveMentality').onchange=tactical;
 $('makeSub').onclick=()=>handle(()=>Engine.substitute(s,m,t.id,+$('subOut').value,+$('subIn').value));
 }
 if(live&&m.finished)$('matchCommit').onclick=()=>{stopMatchClock();Engine.finishRound(s);$('matchDialog').close();render();message('Jornada concluída. Resultados e estatísticas actualizados na carreira.');};
}
